renderIntro:
function renderIntro() {
  if (amHub) { amUpdateHeader(); document.getElementById('drillContainer').innerHTML = amHubHtml(); return; }
  if (timerInterval) clearInterval(timerInterval);
  populateSectionSelect();

  const counts = [10,20,30,50,-1];
  const countLabels = ['10','20','30','50','All'];
  const pool = getPool();
  const flags = {en:'🇬🇧',fr:'🇫🇷',it:'🇮🇹'};
  const names = {en:'English',fr:'French',it:'Italian'};
  const D = DATA();

  // Build section dropdown: ALL SECTIONS + All of A/B/C... + individual sections (all caps)
  const allSections = [...new Set(D.map(d => d.section_en))];
  const letters = [...new Set(allSections.map(s => s.match(/^([A-E])/i)?.[1]?.toUpperCase()).filter(Boolean))].sort();

  if (currentSection === '__MULTI__' && !amMultiTopics.length) currentSection = allSections[0];
  let sectionOptStr = amMultiTopics.length ? `<option value="__MULTI__"${currentSection==='__MULTI__'?' selected':''}>✔ MY SELECTION (${amMultiTopics.length} topic${amMultiTopics.length===1?'':'s'})</option>` : '';
  sectionOptStr += `<option value="__ALL__"${currentSection==='__ALL__'?' selected':''}>★ ALL SECTIONS</option>`;
  letters.forEach(letter => {
    const letterSections = allSections.filter(s => s.toUpperCase().startsWith(letter+':') || s.toUpperCase().startsWith(letter+' :'));
    const allKey = `__${letter}__`;
    sectionOptStr += `<option value="${allKey}"${currentSection===allKey?' selected':''}>── All of ${letter} ──</option>`;
    letterSections.forEach(s => {
      sectionOptStr += `<option value="${s}"${s===currentSection?' selected':''}>&nbsp;&nbsp;${s.toUpperCase()}</option>`;
    });
  });

  // Build subsection options for current section group
  let subFiltered;
  if (currentSection === '__MULTI__') {
    subFiltered = D.filter(d => amMultiTopics.indexOf(d.subsection_en) !== -1);
  } else if (currentSection === '__ALL__') {
    subFiltered = D;
  } else if (currentSection && currentSection.startsWith('__') && currentSection.endsWith('__')) {
    const letter = currentSection.slice(2,-2);
    subFiltered = D.filter(d => d.section_en.toUpperCase().startsWith(letter+':') || d.section_en.toUpperCase().startsWith(letter+' :'));
  } else {
    subFiltered = D.filter(d => d.section_en === currentSection);
  }
  const subsNames = [...new Set(subFiltered.map(d => d.subsection_en))];
  if (currentSubsection !== 'all') {
    const match = subsNames.find(n => normTopic(n) === normTopic(currentSubsection));
    currentSubsection = match || 'all';
  }
  const totalPhrases = subFiltered.reduce((a,s)=>a+Math.max((s.phrases_en||[]).length,(s.phrases_fr||[]).length),0);
  const subsOpts = `<option value="all"${currentSubsection==='all'?' selected':''}>All topics (${totalPhrases} phrases)</option>` +
    subsNames.map(s => `<option value="${amEsc(s)}"${s===currentSubsection?' selected':''}>${amEsc(amSubLbl(s))}</option>`).join('');
  const sectionOpts = (currentSection ? '' : '<option value="" selected></option>') + sectionOptStr;

  const L = amSetLangs();
  const fromOpts = L.map(l => `<option value="${l}"${l===fromLang?' selected':''}>${flags[l]} ${names[l]}</option>`).join('');
  const toOpts   = L.map(l => `<option value="${l}"${l===toLang?' selected':''}>${flags[l]} ${names[l]}</option>`).join('');

  const startN = amStartCount(pool.length);
  const blank = !currentSection, dis = pool.length ? '' : ' disabled';   // nothing chosen yet: the Start buttons wait
  const boxLabel = blank ? '' : getSectionLabel(currentSection) + (currentSubsection !== 'all' && currentSection !== '__MULTI__' ? ' · ' + amSubLbl(currentSubsection) : '');
  const isAM = amSet === 'am';
  const container = document.getElementById('drillContainer');
  container.innerHTML = `
    <div class="aph-wrap am-home">
    <div style="padding:0 0 8px"><button class="aph-btn aph-btn-sm" onclick="amToHub()">&larr; Back</button></div>
    <div class="aph-card intro-card${isAM ? ' am-set-am' : ' am-set-ps'}">
      <h2 class="aph-h">${blank ? 'Choose your topics to begin' : 'Ready to practise?'}</h2>
      ${amLinkNoteHtml()}

      <div class="am-cols"><div class="am-col">
      <div class="aph-label" style="margin-top:4px">Direction</div>
      <div class="aph-row">
        <select class="aph-select" id="intro-from" onchange="onDirChange()">${fromOpts}</select>
        <button class="aph-swap" onclick="introSwapDir()">&#8644; Swap</button>
        <select class="aph-select" id="intro-to" onchange="onDirChange()">${toOpts}</select>
      </div>
      <div class="aph-label">Mix both ways</div>
      <div class="aph-row" id="mix-row">${mixChips('setMix', mixMode)}<span class="aph-note" id="mix-note">${mixNoteText()}</span></div>
      ${amSoonNote()}

      <div class="aph-label">Topics <span class="aph-note" style="font-weight:600;text-transform:none;letter-spacing:0">(tap to choose one or more)</span></div>
      <div class="aph-row">
        <button type="button" id="amTopicBox" class="aph-select am-pick-btn am-wide${blank ? ' am-pick-none' : ''}" onclick="openAMOverview()">${blank ? '<em>Nothing chosen yet</em>' : amEsc(boxLabel)} <span class="am-pick-car">&#9662;</span></button>
        <select class="aph-select am-wide" id="intro-section" onchange="onSectionChange()" style="display:none" aria-hidden="true" tabindex="-1">${sectionOpts}</select>
        <select class="aph-select am-wide" id="intro-subsection" onchange="onSubChange()" style="display:none" aria-hidden="true" tabindex="-1">${subsOpts}</select>
        <span class="aph-note intro-phrase-count">${blank ? '' : pool.length + ' phrases'}</span>
      </div>

      </div><div class="am-col">
      <div class="aph-label">Cards per session</div>
      <div class="aph-row">
        ${counts.map((n,i) => `<button class="aph-chip${_selectedCount===n?' on':''}" onclick="setSelectedCount(${n})">${countLabels[i]}</button>`).join('')}
      </div>

      <div class="aph-label">Timer per card</div>
      <div class="aph-row">
        <button class="aph-step" onclick="adjustTimer(-1)">&#8722;</button>
        <span class="aph-step-val" id="timer-display">${timerSeconds}s</span>
        <button class="aph-step" onclick="adjustTimer(1)">+</button>
      </div>

      </div></div>

      <div class="aph-stack" style="margin-top:22px">
        ${isAM ? `<div class="am-study-row">
          <button class="aph-btn aph-btn-block am-read-btn"${dis} onclick="startReadListen()">&#128214; Read &amp; listen</button>
          <button class="aph-btn aph-btn-primary aph-btn-block"${dis} onclick="introStartDrill()">&#9654; Start Drill · <span id="startCount">${pool.length ? startN + ' card' + (startN===1?'':'s') : 'choose topics first'}</span></button>
        </div>` : `<button class="aph-btn aph-btn-primary aph-btn-block"${dis} onclick="introStartDrill()">&#9654; Start Drill · <span id="startCount">${pool.length ? startN + ' card' + (startN===1?'':'s') : 'choose topics first'}</span></button>`}
        <button class="aph-btn aph-btn-block"${dis} onclick="introStartLeisure()">&#9749; Leisure Mode</button>
        <div class="aph-tools ${isAM ? 'am-tools3' : 'am-tools2'}">
          <button id="autotimeBtn" onclick="toggleAutotime()" class="aph-btn${isAutotime?' on':''}">⏱ Autotime: ${isAutotime?'On':'Off'}</button>
          <button onclick="showAMTestPanel()"${dis} class="aph-btn">&#128221; Generate Test</button>
          ${isAM ? '<button id="amVpBtn"' + dis + ' onclick="amvpOpen()" class="aph-btn">&#128214; View &amp; Print</button>' : ''}
        </div>
        ${editModeUnlocked ? '<div class="aph-tools" style="grid-template-columns:repeat(2,minmax(0,1fr))"><button onclick="showAMPracticePdf()" class="aph-btn">&#128424; ' + amSetName() + '</button><button onclick="openAMStudyPDF()" class="aph-btn">&#128424; Study Sheet</button></div>' : ''}
      </div>

      <div class="aph-keys">
        <span><span class="aph-key bad">&#8592;</span>major error</span>
        <span><span class="aph-key near">&#8595;</span>nearly</span>
        <span><span class="aph-key ok">&#8594;</span>got it</span>
      </div>
    </div>
    </div>`;
}

populateSectionSelect:
function populateSectionSelect() {
  const select = document.getElementById('sectionSelect');
  select.innerHTML = '';

  const sections = [];
  const seen = new Set();
  DATA().forEach(item => {
    if (!seen.has(item.section_en)) {
      sections.push(item.section_en);
      seen.add(item.section_en);
    }
  });

  sections.forEach(section => {
    const option = document.createElement('option');
    option.value = section;
    option.textContent = section.toUpperCase();
    select.appendChild(option);
  });

  populateSubsectionSelect();   // no default section: a boy chooses his topics

}

amFilterTopics:
function amFilterTopics() {
  const D = DATA();
  if (!currentSection) return [];
  if (currentSection === '__MULTI__') return D.filter(item => amMultiTopics.indexOf(item.subsection_en) !== -1).filter(subMatches);
  if (currentSection === '__ALL__') return D.filter(subMatches);
  if (currentSection.startsWith('__') && currentSection.endsWith('__')) {
    const letter = currentSection.slice(2, -2);
    return D.filter(item => item.section_en.toUpperCase().startsWith(letter + ':') || item.section_en.toUpperCase().startsWith(letter + ' :')).filter(subMatches);
  }
  if (currentSubsection === 'all') return D.filter(item => item.section_en === currentSection);
  return D.filter(item => item.section_en === currentSection && subMatches(item));
}

introStartDrill:
function introStartDrill() {
  const s = document.getElementById('intro-section');
  const sub = document.getElementById('intro-subsection');
  const f = document.getElementById('intro-from');
  const t = document.getElementById('intro-to');
  if (s) currentSection = s.value;
  if (sub) currentSubsection = sub.value;
  if (f) fromLang = f.value;
  if (t) toLang = t.value;
  if (!currentSection) { alert('Choose at least one topic first.'); return; }
  startQuickDrill(_selectedCount);
}

