openAMOverview:
function openAMOverview(){
  amEnhanceOverview();
  amOverviewTicks = currentSection ? [...new Set(amFilterTopics().map(d => d.subsection_en))] : [];   // what the set-up screen shows now
  amRefreshOverview();
  amOvModal().style.display = 'block';
}

amOverviewUse:
function amOverviewUse(){
  if (!amOverviewTicks.length) return;
  // keep Overview order so tests list topics sensibly
  amMultiTopics = DATA().map(d => d.subsection_en).filter(t => amOverviewTicks.indexOf(t) !== -1);
  amOvModal().style.display = 'none';
  if (amMultiTopics.length >= new Set(DATA().map(d => d.subsection_en)).size) {
    currentSection = '__ALL__'; currentSubsection = 'all'; amMultiTopics = [];
  } else if (amMultiTopics.length === 1) {
    const hit = DATA().find(d => d.subsection_en === amMultiTopics[0]);
    currentSection = hit.section_en; currentSubsection = hit.subsection_en;
  } else {
    currentSection = '__MULTI__'; currentSubsection = 'all';
  }
  clearAMTestOutput();
  renderIntro();
}

amEnhanceOverview:
function amEnhanceOverview(){
  const modal = amOvModal();
  if (!modal || modal.dataset.enhanced) return;
  modal.dataset.enhanced = '1';
  modal.querySelectorAll('div[onclick^="selectAMTopic("]').forEach(el => {
    el.setAttribute('data-am-call', el.getAttribute('onclick'));
    el.removeAttribute('onclick');
    const info = amParseOverviewCall(el);
    if (!info) return;
    if (info.sub === 'all') {
      el.setAttribute('data-am-section', info.section);
      el.title = 'Tick or untick every topic in this section';
      el.addEventListener('click', () => amToggleSection(info.section));
    } else {
      el.setAttribute('data-am-topic', info.sub);
      el.style.alignItems = 'flex-start';
      const cb = document.createElement('input');
      cb.type = 'checkbox'; cb.tabIndex = -1;
      cb.style.cssText = 'margin:2px 4px 0 0;accent-color:#1a2744;pointer-events:none;flex-shrink:0;';
      el.insertBefore(cb, el.firstChild);
      el.addEventListener('click', () => amToggleTopic(info.sub));
    }
  });
  // Sticky action bar
  const card = modal.firstElementChild;
  const bar = document.createElement('div');
  bar.id = 'amOverviewBar';
  bar.innerHTML = '<span id="amOverviewCount"></span>'
    + '<button class="aph-btn aph-btn-sm" onclick="amOverviewAll()">Tick all</button>'
    + '<button class="aph-btn aph-btn-sm" onclick="amOverviewClear()">Clear ticks</button>'
    + '<button id="amOverviewUse" class="aph-btn aph-btn-primary" onclick="amOverviewUse()" style="min-height:44px;font-size:.9375rem;padding:10px 16px;">Use ticked topics</button>';
  card.appendChild(bar);
}
